/* cppi::04bffd45b62c7ee2904d369ed76b8bc4b2303745c6192be6cd5c201755b2b3c0 */
select business_date as date_, security_id, classification_code_2, ROW_NUMBER() over (partition by business_date, id_vendor_security_ndo order by feed_version asc, id_cppib_index asc) as rn from market.cppib_market_index_constituents_mapped_rimes where business_date between date '2025-06-17' and date '2025-06-18'
    and security_id is not null and weight_ndo >0  and id_cppib_index in ('SP500_GR_USD_0_0','SP500_10_GR_USD_0_0','SP500_15_GR_USD_0_0','SP500_20_GR_USD_0_0','SP500_25_GR_USD_0_0','SP500_30_GR_USD_0_0','SP500_35_GR_USD_0_0','SP500_40_GR_USD_0_0','SP500_45_GR_USD_0_0','SP500_50_GR_USD_0_0','SP500_55_GR_USD_0_0','SP500_60_GR_USD_0_0')

/* cppi::7bf664d82a57556dcb40ef6ce29454244579a7b5df96a000915184e9e0168fff */
SELECT business_date, extract_timestamp, dc_trade_date FROM "ci_etl_db_dev"."ci_capital_pipeline_dealcloud_staging"
where run_id = '8a21d570-7745-4efb-8187-f0abee390075' --2293

/* cppi::09511039a438dc3c727ee602867ff733befafce194d293f624eea22f543f2c13 */
select security_id, barra_id from asset.cppib_asset_vendor_id_mapping where pit_date = date'2025-06-18' 
                                      and market_status='ACTV' and primary_flg='Y' and trading_item_id is not null

/* cppi::f2da25e990838955f7f23f7a10767a778f7c3d852d9297676a126249ad23325c */
select id_isin as identifier, cppib_sec_id as ID_CPPIBSEC, ticker_exch_cd as ticker from asset.qsrp_security_equity_latest
     where id_isin is not null and cppib_sec_id is not null

