/* cppi::b4f8be3839d993a8c9cc821af006afb482a60ad483a91c425b96308103755299 */
select business_date as date_, security_id, 'SP500_30' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-18' and business_date <= date '2025-06-18' and weight_ndo>0 and id_cppib_index = 'SP500_30_GR_USD_0_0' and security_id is not null

/* cppi::d9fc09bbe4cef3f2ff5e20c891a192254641969765f483b9379068c3cbe23f53 */
